/**
 * Sentry SDK wrapper.
 *
 * Not meant to be used directly by the rest of the system -- access
 * functionality through `ui/analytics.js` instead.
 *
 * The web-server will require SENTRY_AUTH_TOKEN to publish source-maps.
 *
 * -- How to debug --
 * Add the following local-storage flags from devtools:
 *   sentry_install  : true         // force install
 *   sentry_debug    : true         // enables verbose logging
 *   sentry_test_dsn : https://blah // if you have your own DSN
 */
// @if process.env.FLOSS_BUILD!='true'
import * as Sentry from '@sentry/react';
// @endif
import { LocalStorage } from 'util/storage';
const SENTRY_DSN = 'https://1f3c88e2e4b341328a638e138a60fb73@sentry.odysee.tv/2';
const TEST_DSN = LocalStorage.getItem('sentry_test_dsn') || '';
const IS_PRODUCTION = process.env.NODE_ENV === 'production';
const FORCE_INSTALL = LocalStorage.getItem('sentry_install') === 'true';
let gSentryInitialized = false;
let gSentryEnabled = false; // ****************************************************************************
// sentryWrapper
// ****************************************************************************

declare type SentryWrapper = {
  init: () => void;
  setState: (enable: boolean) => void;
  log: (
    error: Error | string,
    options?: SentryEventOptions,
    transactionName?: string
  ) => Promise<LogId | null | undefined>;
};
export const sentryWrapper: SentryWrapper = {
  init: () => {
    // @if process.env.FLOSS_BUILD='true'
    return;
    // @endif
    // Call init() as early as possible in the app.
    // Note that we currently catch React errors in 'component/errorBoundary' and
    // manually relay it to Sentry. Those will not bubble up to this error reporter.
    if (IS_PRODUCTION || FORCE_INSTALL) {
      // https://docs.sentry.io/platforms/javascript/configuration/options/
      Sentry.init({
        dsn: TEST_DSN || SENTRY_DSN,
        beforeBreadcrumb: handleBeforeBreadcrumb,
        beforeSend: handleBeforeSend,
        debug: LocalStorage.getItem('sentry_debug') === 'true',
        denyUrls: [/extensions\//i, /^chrome:\/\//i],
        maxBreadcrumbs: 50,
        release: process.env.BUILD_REV,
        tracesSampleRate: 0.0,
        allowUrls: FORCE_INSTALL ? null : [/https:\/\/((.*)\.)?odysee\.(com|tv)/],
      });
      gSentryInitialized = true;
    }
  },
  setState: (enable: boolean) => {
    gSentryEnabled = enable;
  },
  log: (error: Error | string, options?: SentryEventOptions, transactionName?: string) => {
    return new Promise((resolve) => {
      // @if process.env.FLOSS_BUILD='true'
      resolve(null);
      return;
      // @endif
      if (gSentryInitialized && gSentryEnabled) {
        Sentry.withScope((scope) => {
          if (transactionName) {
            // Using transactionName as the label is somewhat of a hack:
            // https://stackoverflow.com/questions/72133586/how-can-i-change-the-name-or-message-of-a-javascript-error-object-used-in-sentry
            scope.setTransactionName(transactionName);
          }

          const eventId =
            typeof error === 'string'
              ? Sentry.captureMessage(error, reformatTagKeys(options) as any)
              : Sentry.captureException(error, reformatTagKeys(options) as any);
          resolve(eventId);
        });
      } else {
        resolve(null);
      }
    });
  },
};

// ****************************************************************************
// Private
// ****************************************************************************
function handleBeforeSend(event, hints) {
  try {
    const ev = event.exception?.values || [];
    const msg = ev[0]?.value || '';

    if (msg.includes('NO_TARGET') || msg.includes('DESTROYED')) {
      return null;
    }

    // Stale chunk / lazy-import failures — already handled by ErrorBoundary auto-reload.
    if (
      /[._]result\.default|reading 'default'|_result is undefined|evaluating.*_result|ChunkLoadError|dynamically imported module|Importing a module script failed|Unable to preload CSS|Lazy element type must resolve|Received a promise that resolves to: undefined|Minified React error #306|undefined is not an object \(evaluating '\$?\w+\.(use[A-Z]|jsxs?|jsxDEV|Fragment|createElement|cloneElement|forwardRef|memo)/i.test(
        msg
      )
    ) {
      return null;
    }

    const frames = ev[0]?.stacktrace?.frames || [];
    const lastFrame = frames[frames.length - 1];

    if (lastFrame?.filename && lastFrame.filename.match(/([a-z]*)-extension:\/\//)) {
      return null;
    }

    if (frames.length > 0 && frames.every((f) => f.filename === '<anonymous>')) {
      event.fingerprint = ['all-anonymous-frames'];
    }
  } catch {}

  return event;
}

function handleBeforeBreadcrumb(breadcrumb, hint) {
  // https://docs.sentry.io/platforms/javascript/configuration/filtering/
  return breadcrumb;
}

/**
 * Appends an underscore to all our custom keys so that they appear first before
 * the Sentry-generated ones in the dashboard.
 * - Doing it here so that developers don't need to.
 * - Changes is done in-place and object is returned for chaining convenience.
 *
 * @param options
 */
function reformatTagKeys(options?: SentryEventOptions) {
  if (options && options.tags) {
    const keys = Object.keys(options.tags);

    for (let i = 0; i < keys.length; ++i) {
      const key = keys[i];

      if (!key.startsWith('_')) {
        options.tags[`_${key}`] = options.tags[key];
        delete options.tags[key];
      }
    }
  }

  return options;
}
