export const doBeginPublish = (type: PublishType, name: string = '', customPath: string = '') => {
  return (dispatch: Dispatch, getState: GetState) => {
    assert(PUBLISH_PATH_MAP[type], 'invalid type', type);

    const state = getState();
    const currentType = state.publish.type;
    const currentFormId = state.publish.activeFormId;

    if (!(currentType === type && currentFormId)) {
      if (currentFormId) {
        dispatch({ type: 'PUBLISH_SAVE_FORM', data: { id: currentFormId } });
      }
      dispatch(doClearPublish());
      dispatch(
        batchActions(
          { type: 'PUBLISH_SET_ACTIVE_FORM', data: { id: null } },
          { type: ACTIONS.UPDATE_PUBLISH_FORM, data: { type } }
        )
      );
    }

    if (name) {
      dispatch({ type: ACTIONS.UPDATE_PUBLISH_FORM, data: { name } });
    }

    if (customPath) {
      navigateTo(customPath);
    } else {
      const path = PUBLISH_PATH_MAP[type] || PUBLISH_PATH_MAP.file;
      navigateTo(`/$/${path}`);
    }
  };
};
export const doClearPublish = () => (dispatch: Dispatch, getState: GetState) => {
  const state = getState();
  const defaultChannelClaim = selectDefaultChannelClaim(state);
  const channelLanguages = makeSelectMetadataItemForUri(defaultChannelClaim?.permanent_url, 'languages')(state);
  const channelPrimaryLanguage = channelLanguages ? channelLanguages[0] : null;
  dispatch({
    type: ACTIONS.CLEAR_PUBLISH,
    data: {
      language: channelPrimaryLanguage,
    },
  });
  return dispatch(doResetThumbnailStatus());
};
