export const doUpdateTitle = (title: string, skipNameAutoFill: boolean) => (dispatch: Dispatch, getState: GetState) => {
  const state = getState();
  const { name, claimToEdit } = state.publish;
  const regexInvalidURI =
    /[ =&#:$@%?;/\\\n"<>%{}|^~[\]`\u{0000}-\u{0008}\u{000b}-\u{000c}\u{000e}-\u{001F}\u{D800}-\u{DFFF}\u{FFFE}-\u{FFFF}]/gu; // eslint-disable-line no-control-regex
  const publishFormValue = {
    name,
    title,
  };
  // Keep the name matching the title, if the name was already matching
  let newName = title.replace(regexInvalidURI, '-');

  if (
    !claimToEdit &&
    !skipNameAutoFill &&
    (newName.startsWith(name) || newName === name.slice(0, -1) || !title || !name)
  ) {
    publishFormValue.name = newName;
  }

  dispatch({
    type: ACTIONS.UPDATE_PUBLISH_FORM,
    data: { ...publishFormValue },
  });
};
/** Fallback metadata extraction via <video> element when MediaBunny is unavailable */
function extractMetadataViaVideoElement(blob: Blob, dispatch: Dispatch, shouldApplyMetadata: () => boolean) {
  window.URL = window.URL || window.webkitURL;
  const video = document.createElement('video');
  const objectUrl = window.URL.createObjectURL(blob);

  const cleanup = () => {
    window.URL.revokeObjectURL(objectUrl);
    video.removeAttribute('src');
    video.load();
  };

  video.preload = 'metadata';
  video.addEventListener('loadedmetadata', () => {
    if (!shouldApplyMetadata()) {
      cleanup();
      return;
    }

    dispatch({
      type: ACTIONS.UPDATE_PUBLISH_FORM,
      data: {
        fileDur: video.duration,
        fileBitrate: getVideoBitrate(blob.size, video.duration),
      },
    });
    cleanup();
  });
  video.addEventListener('error', () => {
    if (!shouldApplyMetadata()) {
      cleanup();
      return;
    }

    dispatch({
      type: ACTIONS.UPDATE_PUBLISH_FORM,
      data: { fileDur: 0, fileBitrate: 0 },
    });
    cleanup();
  });
  video.src = objectUrl;
}

export const doUpdateFile = (file: WebFile, clearName: boolean = true) => {
  return (dispatch: Dispatch, getState: GetState) => {
    const state = getState();
    const { name, title, type, liveCreateType, liveEditType, editingURI } = state.publish;
    const isStillEditing = selectIsStillEditing(state);
    const preserveLivestreamReplayEditMetadata =
      type === 'livestream' &&
      Boolean(editingURI) &&
      liveCreateType === 'edit_placeholder' &&
      liveEditType === 'upload_replay';

    if (!file) {
      // This also handles the case of trying to select another file but canceling half way.
      if (isStillEditing || !clearName) {
        dispatch({
          type: ACTIONS.UPDATE_PUBLISH_FORM,
          data: {
            filePath: '',
            fileDur: 0,
            fileBitrate: 0,
            fileVideoCodec: '',
            fileAudioCodec: '',
            fileFormat: '',
            fileWidth: 0,
            fileHeight: 0,
            fileFps: 0,
            fileNeedsTransmux: false,
            fileText: undefined,
          },
        });
      } else {
        dispatch({
          type: ACTIONS.UPDATE_PUBLISH_FORM,
          data: {
            filePath: '',
            name: '',
            fileDur: 0,
            fileBitrate: 0,
            fileVideoCodec: '',
            fileAudioCodec: '',
            fileFormat: '',
            fileWidth: 0,
            fileHeight: 0,
            fileFps: 0,
            fileNeedsTransmux: false,
            fileText: undefined,
          },
        });
      }

      return;
    }

    assert(typeof file !== 'string');
    const selectedFilePath = file.path || file;
    const shouldApplyMetadata = () => selectPublishFormValue(getState(), 'filePath') === selectedFilePath;
    const contentType = file.type && typeof file.type === 'string' && file.type.split('/');
    const isVideo = contentType ? contentType[0] === 'video' : false;
    const isMp4 = contentType ? contentType[1] === 'mp4' : false;
    let isTextPost = false;

    if (contentType && contentType[0] === 'text') {
      isTextPost = contentType[1] === 'plain' || contentType[1] === 'markdown'; // setCurrentFileType(contentType);
    } else if (file.name) {
      // If user's machine is missing a valid content type registration
      // for markdown content: text/markdown, file extension will be used instead
      const extension = file.name.split('.').pop();
      const MARKDOWN_FILE_EXTENSIONS = ['txt', 'md', 'markdown'];
      isTextPost = MARKDOWN_FILE_EXTENSIONS.includes(extension);
    }

    const fileExtension = file.name?.toLowerCase().split('.').pop() || '';
    const isMp4Container = fileExtension === 'mp4' || fileExtension === 'mov' || fileExtension === 'm4v';

    const formUpdates: UpdatePublishState = {
      fileSize: file.size,
      fileMime: file.type,
      fileVid: isVideo,
      fileDur: 0,
      fileBitrate: 0,
      fileVideoCodec: '',
      fileAudioCodec: '',
      fileFormat: fileExtension,
      fileWidth: 0,
      fileHeight: 0,
      fileFps: 0,
      fileNeedsTransmux: isVideo && !isMp4Container,
      fileSizeTooBig: false,
      fileText: undefined,
    };

    // --- Async metadata extraction via MediaBunny ---
    const isMedia = isVideo || (contentType && contentType[0] === 'audio');
    if (isMedia) {
      import('odysee-media-usagi')
        .then(async (mb) => {
          let input;

          try {
            input = new mb.Input({
              formats: mb.ALL_FORMATS,
              source: new mb.BlobSource(file as unknown as Blob),
            });

            const duration = (await input.computeDuration()) || 0;
            const videoTrack = await input.getPrimaryVideoTrack();
            const audioTrack = await input.getPrimaryAudioTrack();

            const metadataUpdates: UpdatePublishState = {
              fileDur: duration,
              fileBitrate: duration > 0 ? (file.size * 8) / duration : 0,
            };

            if (videoTrack) {
              const packetStats = await videoTrack.computePacketStats(120);
              metadataUpdates.fileVideoCodec = videoTrack.codec || '';
              metadataUpdates.fileWidth = videoTrack.displayWidth || 0;
              metadataUpdates.fileHeight = videoTrack.displayHeight || 0;
              metadataUpdates.fileFps = packetStats.averagePacketRate || 0;
            }
            if (audioTrack) {
              metadataUpdates.fileAudioCodec = audioTrack.codec || '';
            }

            // Detect non-MP4 containers for transmux prompt
            metadataUpdates.fileFormat = isMp4Container ? 'mp4' : fileExtension;
            metadataUpdates.fileNeedsTransmux = isVideo && !isMp4Container;

            if (shouldApplyMetadata()) {
              dispatch({
                type: ACTIONS.UPDATE_PUBLISH_FORM,
                data: metadataUpdates,
              });
            }
          } catch (e) {
            console.warn('[Publish] MediaBunny metadata extraction failed, falling back:', e); // eslint-disable-line no-console
            // Fallback: try <video> element for MP4
            if (isMp4) {
              extractMetadataViaVideoElement(file as unknown as Blob, dispatch, shouldApplyMetadata);
            }
          } finally {
            if (input) {
              input.dispose();
            }
          }
        })
        .catch(() => {
          // MediaBunny not available — fallback to <video> element
          if (isMp4) {
            extractMetadataViaVideoElement(file as unknown as Blob, dispatch, shouldApplyMetadata);
          }
        });
    } else {
      formUpdates.fileDur = 0;

      if (isTextPost) {
        const reader = new FileReader();
        reader.addEventListener('load', (event: ProgressEvent) => {
          // See: https://github.com/facebook/flow/issues/3470
          if (event.target instanceof FileReader) {
            const text = event.target.result;
            dispatch({
              type: ACTIONS.UPDATE_PUBLISH_FORM,
              data: {
                fileText: text,
              },
            }); // setPublishMode(PUBLISH_MODES.POST);
          }
        });
        reader.readAsText(file as unknown as Blob); // setCurrentFileType('text/markdown');
      }
    }

    // --- File Size ---
    const TV_PUBLISH_SIZE_LIMIT_BYTES = WEB_PUBLISH_SIZE_LIMIT_GB * 1073741824;

    if (file.size && Number(file.size) > TV_PUBLISH_SIZE_LIMIT_BYTES) {
      formUpdates.fileSizeTooBig = true;
    }

    // --- Name and title ---
    // Strip off extension and replace invalid characters
    const newFileName = (file.name && file.name.substr(0, file.name.lastIndexOf('.'))) || '';
    const fileName = clearName ? newFileName : name || newFileName;

    if (!preserveLivestreamReplayEditMetadata && (clearName || !title)) {
      formUpdates.title = newFileName || fileName;
    }

    if (!preserveLivestreamReplayEditMetadata && !isStillEditing && clearName) {
      formUpdates.name = sanitizeName(newFileName || fileName);
    } else if (!preserveLivestreamReplayEditMetadata && !isStillEditing && !name) {
      formUpdates.name = sanitizeName(fileName);
    }

    // --- File Path ---
    // If electron, we'll set filePath to the path string because SDK is handling publishing.
    // File.path will be undefined from web due to browser security, so it will default to the File Object.
    formUpdates.filePath = selectedFilePath;
    // --- Finalize ---
    dispatch({
      type: ACTIONS.UPDATE_PUBLISH_FORM,
      data: formUpdates,
    });
  };
};
export const doUploadThumbnail =
  (filePath?: string, thumbnailBlob?: File, fsAdapter?: any, fs?: any, path?: any, cb?: (arg0: string) => void) =>
  (dispatch: Dispatch) => {
    let thumbnail, fileExt, fileName, fileType, stats, size;

    const uploadError = (error: string | { message: string; cause: string } = '') => {
      dispatch(
        batchActions(
          {
            type: ACTIONS.UPDATE_PUBLISH_FORM,
            data: {
              uploadThumbnailStatus: THUMBNAIL_STATUSES.READY,
              thumbnail: '',
              nsfw: false,
            },
          },
          doError(error)
        )
      );
    };

    dispatch({
      type: ACTIONS.UPDATE_PUBLISH_FORM,
      data: {
        thumbnailError: undefined,
      },
    });

    const doUpload = (data) => {
      return fetch(IMG_CDN_PUBLISH_URL, {
        method: 'POST',
        body: data,
      })
        .then((res) => res.text())
        .then((text) => {
          try {
            return text.length ? JSON.parse(text) : {};
          } catch {
            throw new Error(text);
          }
        })
        .then((json) => {
          if (json.type !== 'success') {
            return uploadError(
              json.message || __('There was an error in the upload. The format or extension might not be supported.')
            );
          }

          if (cb) {
            cb(json.message);
          }

          return dispatch({
            type: ACTIONS.UPDATE_PUBLISH_FORM,
            data: {
              uploadThumbnailStatus: THUMBNAIL_STATUSES.COMPLETE,
              thumbnail: json.message,
            },
          });
        })
        .catch((err) => {
          let message = err.message;

          // This sucks but ¯\_(ツ)_/¯
          if (message === 'Failed to fetch') {
            // message = __('Thumbnail upload service may be down, try again later.');
            message = __(
              'Thumbnail upload service may be down, try again later. Some plugins like AdGuard Français may be blocking the service. If using Brave, go to brave://adblock and disable it, or turn down shields.'
            );
          }

          const userInput = [fileName, fileExt, fileType, thumbnail, size];
          uploadError({
            message,
            cause: userInput.join(' | '),
          });
        });
    };

    dispatch({
      type: ACTIONS.UPDATE_PUBLISH_FORM,
      data: {
        uploadThumbnailStatus: THUMBNAIL_STATUSES.IN_PROGRESS,
      },
    });

    if (fsAdapter && fsAdapter.readFile && filePath) {
      fsAdapter.readFile(filePath, 'base64').then((base64Image) => {
        fileExt = 'png';
        fileName = 'thumbnail.png';
        fileType = 'image/png';

        const byteString = atob(base64Image);
        const arrayBuffer = new ArrayBuffer(byteString.length);
        const uint8Array = new Uint8Array(arrayBuffer);
        for (let i = 0; i < byteString.length; i++) {
          uint8Array[i] = byteString.charCodeAt(i);
        }
        const blob = new Blob([uint8Array], { type: fileType });
        const uploadFile = new File([blob], fileName, { type: fileType });

        const data = new FormData();
        data.append('file-input', uploadFile);
        data.append('upload', 'Upload');
        return doUpload(data);
      });
    } else {
      if (filePath && fs && path) {
        thumbnail = fs.readFileSync(filePath);
        fileExt = path.extname(filePath);
        fileName = path.basename(filePath);
        stats = fs.statSync(filePath);
        size = stats.size;
        fileType = `image/${fileExt.slice(1)}`;
      } else if (thumbnailBlob) {
        fileExt = `.${
          thumbnailBlob.type && typeof thumbnailBlob.type === 'string' && thumbnailBlob.type.split('/')[1]
        }`;
        fileName = thumbnailBlob.name;
        fileType = thumbnailBlob.type;
        size = thumbnailBlob.size;
      } else {
        return null;
      }

      if (size && size >= THUMBNAIL_CDN_SIZE_LIMIT_BYTES) {
        const maxSizeMB = THUMBNAIL_CDN_SIZE_LIMIT_BYTES / (1024 * 1024);
        uploadError(
          __('Thumbnail size over %max_size%MB, please edit and reupload.', {
            max_size: maxSizeMB,
          })
        );
        return;
      }

      const data = new FormData();
      const file =
        thumbnailBlob ||
        (thumbnail &&
          new File([thumbnail], fileName, {
            type: fileType,
          }));
      data.append('file-input', file);
      data.append('upload', 'Upload');
      return doUpload(data);
    }
  };
export const doPrepareEdit = (claim: StreamClaim, uri: string, claimType: string) => {
  assert(claim, 'doPrepareEdit: claim must not be null', {
    uri,
    claimType,
  });
  return async (dispatch: Dispatch, getState: GetState) => {
    const { name, amount, value = {} } = claim;
    const channelName = (claim && claim.signing_channel && claim.signing_channel.name) || null;
    const channelId = (claim && claim.signing_channel && claim.signing_channel.claim_id) || null;
    const {
      author,
      description,
      // use same values as default state
      // fee will be undefined for free content
      fee = {
        amount: '0',
        currency: 'LBC',
      },
      languages,
      license,
      license_url: licenseUrl,
      thumbnail,
      title,
      tags,
      stream_type,
    } = value;
    let state = getState();
    const isPostClaim = makeSelectFileRenderModeForUri(claim?.permanent_url)(state) === RENDER_MODES.MARKDOWN;
    const isLivestreamClaim = isStreamPlaceholderClaim(claim);
    const type: PublishType = isLivestreamClaim
      ? PUBLISH_TYPES.LIVESTREAM
      : isPostClaim
        ? PUBLISH_TYPES.POST
        : PUBLISH_TYPES.FILE;
    const liveCreateType = isLivestreamClaim ? 'edit_placeholder' : undefined;
    const liveEditType = isLivestreamClaim ? 'update_only' : undefined; // Reverted #2801

    const publishData: UpdatePublishState = {
      type,
      ...(liveCreateType
        ? {
            liveCreateType,
          }
        : {}),
      ...(liveEditType
        ? {
            liveEditType,
          }
        : {}),
      claim_id: claim.claim_id,
      name,
      bid: Number(amount),
      author,
      description,
      fee: { amount: Number(fee.amount), currency: fee.currency },
      languages,
      thumbnail: thumbnail ? thumbnail.url : null,
      title,
      uri,
      uploadThumbnailStatus: thumbnail ? THUMBNAIL_STATUSES.MANUAL : undefined,
      licenseUrl,
      nsfw: isClaimNsfw(claim),
      tags: tags
        ? tags.map((tag) => ({
            name: tag,
          }))
        : [],
      streamType: stream_type,
      claimToEdit: { ...claim },
    };

    // Make sure custom licenses are mapped properly
    // If the license isn't one of the standard licenses, map the custom license and description/url
    if (!CC_LICENSES.some(({ value }) => value === license)) {
      if (!license || license === NONE || license === PUBLIC_DOMAIN) {
        publishData.licenseType = license;
      } else if (license && !licenseUrl && license !== NONE) {
        publishData.licenseType = COPYRIGHT;
      } else {
        publishData.licenseType = OTHER;
      }

      publishData.otherLicenseDescription = license;
    } else {
      publishData.licenseType = license;
    }

    if (channelName) {
      publishData['channel'] = channelName;
    }

    if (channelId) {
      publishData.channelId = channelId;
    }

    // Fill purchase/rental details from the claim
    const rental = parseRentalTag(tags);
    const purchasePrice = parsePurchaseTag(tags);

    if (rental || purchasePrice) {
      publishData['paywall'] = PAYWALL.FIAT;
    } else if (fee.amount && Number(fee.amount) > 0) {
      publishData['paywall'] = PAYWALL.SDK;
    } else {
      publishData['paywall'] = PAYWALL.FREE;
    }

    if (rental) {
      publishData.fiatRentalEnabled = true;
      publishData.fiatRentalFee = {
        amount: rental.price,
        currency: 'USD', // TODO: hardcode until we have a direction on currency
      };
      publishData.fiatRentalExpiration = {
        // Don't know which unit the user picked since we store it as 'seconds'
        // in the tag. Just convert back to days for now.
        value: rental.expirationTimeInSeconds / TO_SECONDS['days'],
        unit: 'days',
      };
    }

    if (purchasePrice) {
      publishData.fiatPurchaseEnabled = true;
      publishData.fiatPurchaseFee = {
        amount: purchasePrice,
        currency: 'USD', // TODO: hardcode until we have a direction on currency
      };
    }

    // == Tag derivations ==
    const publishDataTags = new Set(publishData.tags && publishData.tags.map((tag) => tag.name));

    // -- Membership restrictions
    if (publishDataTags.has(MEMBERS_ONLY_CONTENT_TAG)) {
      if (channelId) {
        // Repopulate membership restriction IDs
        let protectedMembershipIds: Array<number> | void | null = selectProtectedContentMembershipsForContentClaimId(
          state,
          claim.claim_id
        );

        if (protectedMembershipIds === undefined) {
          await dispatch(doMembershipContentforStreamClaimId(claim.claim_id));
          state = getState();
          protectedMembershipIds = selectProtectedContentMembershipsForContentClaimId(state, claim.claim_id);
        }

        if (protectedMembershipIds && protectedMembershipIds.length > 0) {
          publishData.memberRestrictionOn = true;
          publishData.memberRestrictionTierIds = protectedMembershipIds;
        } else {
          publishData.memberRestrictionOn = false;
          publishData.memberRestrictionTierIds = [];
        }
      } else {
        // ??
        if (publishData.tags) {
          publishData.tags = publishData.tags.filter((tag) => tag.name === MEMBERS_ONLY_CONTENT_TAG);
        } else {
          publishData.tags = [];
        }
      }
    }

    // -- Visibility restrictions
    if (tags) {
      if (tags.includes(VISIBILITY_TAGS.UNLISTED)) {
        publishData.visibility = 'unlisted';
      } else if (tags.includes(VISIBILITY_TAGS.PRIVATE)) {
        publishData.visibility = 'private';
      } else if (tags.includes(SCHEDULED_TAGS.HIDE)) {
        publishData.visibility = 'scheduled';
        publishData.scheduledShow = false;
      } else if (tags.includes(SCHEDULED_TAGS.SHOW)) {
        publishData.visibility = 'scheduled';
        publishData.scheduledShow = true;
      } else {
        publishData.visibility = 'public';
      }
    } else {
      publishData.visibility = 'public';
    }

    if (publishData.channelId) {
      dispatch(doSetActiveChannel(publishData.channelId, false));
      dispatch(doSetIncognito(false));
    } else {
      dispatch(doSetIncognito(true));
    }

    dispatch({
      type: ACTIONS.DO_PREPARE_EDIT,
      data: publishData,
    });
    navigateTo(`/$/${PUBLISH_PATH_MAP[type]}`);
  };
};
