// ---------------------------------------------------------------------------
const RECENT_PAGE_SIZE = 100;
const SEARCH_PAGE_SIZE_PER_CHANNEL = 24;

function sortClaimsByNewest(claims: Array<StreamClaim>): Array<StreamClaim> {
  return [...claims].sort((a, b) => {
    const aTime = Number(a?.value?.release_time || a?.meta?.creation_timestamp || 0);
    const bTime = Number(b?.value?.release_time || b?.meta?.creation_timestamp || 0);
    return bTime - aTime;
  });
}

function extractStreamClaims(result: any): Array<StreamClaim> {
  const items = (result && result.items) || [];
  return items.filter((item) => item && item.value_type === 'stream');
}

function clientTitleFilter(claims: Array<StreamClaim>, term: string): Array<StreamClaim> {
  const lower = term.toLowerCase();
  return claims.filter((c) => (c?.value?.title || c?.name || '').toLowerCase().includes(lower));
}

function getLighthouseClaimId(item: any): string | null | undefined {
  if (!item || typeof item !== 'object') return null;
  const rawClaimId = item.claimId || item.claim_id || item.claimID || item.claimid || item.id;
  if (!rawClaimId) return null;
  const claimId = String(rawClaimId).trim();
  return claimId || null;
}

async function hydrateClaimsInStore(dispatch: Dispatch, claims: Array<StreamClaim>): Promise<Array<StreamClaim>> {
  if (!Array.isArray(claims) || claims.length === 0) return [];
  const claimIds = [...new Set(claims.map((claim) => claim?.claim_id).filter(Boolean))];
  if (claimIds.length === 0) return claims;

  try {
    const resolveInfo = await dispatch(doResolveClaimIds(claimIds, true));
    if (!resolveInfo || typeof resolveInfo !== 'object') return claims;
    const resolvedById: Record<string, StreamClaim> = {};
    const resolveValues: Array<any> = Object.values(resolveInfo);
    resolveValues.forEach((info) => {
      const stream: StreamClaim | null | undefined = info && typeof info === 'object' ? info.stream : null;

      if (stream && stream.claim_id && stream.value_type === 'stream') {
        resolvedById[stream.claim_id] = stream;
      }
    });
    return claims.map((claim) => resolvedById[claim.claim_id] || claim);
  } catch {
    // Keep the existing result set if hydration fails; modal search should not hard-fail here.
    return claims;
  }
}

/**
 * Searches the current user's uploads.
 *
 * @param searchTerm - Text query
 * @param filter - Optional visibility filter: 'all' (default) or 'unlisted'
 *
 * For 'all': short queries use claim_list; 3+ char queries use Lighthouse.
 * For 'unlisted': uses claim_search with any_tags for the unlisted tag,
 *   since Lighthouse does not index unlisted content.
 */
export const doSearchMyUploads = (searchTerm: string = '', filter: string = 'all') => {
  return async (dispatch: Dispatch, getState: GetState) => {
    const term = searchTerm.trim();
    const state = getState();
    const showMature = selectShowMatureContent(state);
    const myChannelIds = selectMyChannelClaimIds(state) || [];

    // ── Unlisted filter: use claim_search with any_tags ──
    if (filter === 'unlisted') {
      const csParams: any = {
        page: 1,
        page_size: RECENT_PAGE_SIZE,
        any_tags: [VISIBILITY_TAGS.UNLISTED],
        claim_type: ['stream'],
        order_by: ['release_time'],
        remove_duplicates: true,
      };

      if (myChannelIds.length > 0) {
        csParams.channel_ids = myChannelIds;
      }

      const result = await Lbry.claim_search(csParams);
      const claims = await hydrateClaimsInStore(dispatch, sortClaimsByNewest(extractStreamClaims(result)));
      return {
        claims: term.length > 0 ? clientTitleFilter(claims, term) : claims,
      };
    }

    // ── Scheduled filter: use claim_search with scheduled tags ──
    if (filter === 'scheduled') {
      const csParams: any = {
        page: 1,
        page_size: RECENT_PAGE_SIZE,
        any_tags: Object.values(SCHEDULED_TAGS),
        claim_type: ['stream'],
        order_by: ['release_time'],
        remove_duplicates: true,
      };

      if (myChannelIds.length > 0) {
        csParams.channel_ids = myChannelIds;
      }

      const result = await Lbry.claim_search(csParams);
      const claims = await hydrateClaimsInStore(dispatch, sortClaimsByNewest(extractStreamClaims(result)));
      return {
        claims: term.length > 0 ? clientTitleFilter(claims, term) : claims,
      };
    }

    // ── All uploads: short / empty query → claim_list ──
    if (term.length < 3) {
      const result = await Lbry.claim_list({
        page: 1,
        page_size: RECENT_PAGE_SIZE,
        resolve: true,
        claim_type: ['stream'],
      });
      const claims = await hydrateClaimsInStore(dispatch, sortClaimsByNewest(extractStreamClaims(result)));
      return {
        claims,
      };
    }

    // ── All uploads: no channels → title-filtered recent ──
    if (myChannelIds.length === 0) {
      const result = await Lbry.claim_list({
        page: 1,
        page_size: RECENT_PAGE_SIZE,
        resolve: true,
        claim_type: ['stream'],
      });
      const claims = clientTitleFilter(sortClaimsByNewest(extractStreamClaims(result)), term);
      const hydratedClaims = await hydrateClaimsInStore(dispatch, claims);
      return {
        claims: hydratedClaims,
      };
    }

    // ── All uploads: Lighthouse search across user's channels ──
    const channelIdsCsv = myChannelIds.join(',');
    const queryBase = `from=0&s=${encodeURIComponent(term)}&sort_by=release_time&nsfw=${
      showMature ? 'true' : 'false'
    }&size=${SEARCH_PAGE_SIZE_PER_CHANNEL}`;
    const response = await lighthouse.search(`${queryBase}&channel_id=${encodeURIComponent(channelIdsCsv)}`);
    const claimIds = [];

    if (Array.isArray(response?.body)) {
      response.body.forEach((item) => {
        const claimId = getLighthouseClaimId(item);
        if (claimId) claimIds.push(claimId);
      });
    }

    const uniqueClaimIds = [...new Set(claimIds)];
    const resolveInfo = uniqueClaimIds.length > 0 ? await dispatch(doResolveClaimIds(uniqueClaimIds, true)) : {};
    const resolvedClaims: Array<StreamClaim> = [];

    if (resolveInfo && typeof resolveInfo === 'object') {
      const resolveValues: Array<any> = Object.values(resolveInfo);
      resolveValues.forEach((info) => {
        const stream: StreamClaim | null | undefined = info && typeof info === 'object' ? info.stream : null;
        if (stream && stream.claim_id && stream.value_type === 'stream') resolvedClaims.push(stream);
      });
    }

    return {
      claims: sortClaimsByNewest(resolvedClaims),
    };
  };
};

/**
 * Populates the publish form with metadata from a previously published claim.
 * Unlike doPrepareEdit, this does NOT set editingURI/claimToEdit/name/claim_id,
 * so the form stays in "new upload" mode.
 *
 * @param claim - The source claim to copy from
 * @param fields - Array of field group keys to copy (e.g. ['title', 'description', 'tags', ...])
 */
export const doPopulatePublishFormFromClaim = (claim: StreamClaim, fields: Array<string>) => {
  return async (dispatch: Dispatch, getState: GetState) => {
    if (!claim) return;
    const { value = {} } = claim;
    const {
      description,
      fee = {
        amount: 0,
        currency: 'LBC',
      },
      languages,
      license,
      license_url: licenseUrl,
      thumbnail,
      title,
      tags: claimTags,
    } = value;
    let state = getState();
    const publishData: UpdatePublishState = {};
    const fieldSet = new Set(fields);
    const tags = claimTags || [];
    const normalizedFee = {
      amount: Number(fee.amount) || 0,
      currency: fee.currency || 'LBC',
    };

    // -- Title
    if (fieldSet.has('title')) {
      publishData.title = title || '';
    }

    // -- Description
    if (fieldSet.has('description')) {
      publishData.description = description || '';
    }

    // -- Tags (filter out internal/system tags)
    if (fieldSet.has('tags')) {
      const filteredTags = tags.filter(
        (tag) =>
          tag !== VISIBILITY_TAGS.UNLISTED &&
          tag !== VISIBILITY_TAGS.PRIVATE &&
          tag !== SCHEDULED_TAGS.HIDE &&
          tag !== SCHEDULED_TAGS.SHOW &&
          tag !== MEMBERS_ONLY_CONTENT_TAG
      );
      publishData.tags = filteredTags.map((tag) => ({
        name: tag,
      }));
      // Keep explicit to avoid stale NSFW state from previous form values.
      publishData.nsfw = isClaimNsfw(claim);
    }

    // -- Thumbnail
    if (fieldSet.has('thumbnail')) {
      const thumbnailUrl = thumbnail?.url || '';
      publishData.thumbnail = thumbnailUrl;
      publishData.uploadThumbnailStatus = thumbnailUrl ? THUMBNAIL_STATUSES.MANUAL : THUMBNAIL_STATUSES.READY;
    }

    // -- Language
    if (fieldSet.has('languages')) {
      const normalizedLanguages = languages || [];
      publishData.languages = normalizedLanguages;
      publishData.language = normalizedLanguages[0] || '';
    }

    // -- License
    if (fieldSet.has('license')) {
      publishData.licenseType = NONE;
      publishData.licenseUrl = '';
      publishData.otherLicenseDescription = '';

      if (license) {
        const isStandardLicense = CC_LICENSES.some(({ value }) => value === license);

        if (isStandardLicense) {
          publishData.licenseType = license;
        } else if (license === NONE || license === PUBLIC_DOMAIN) {
          publishData.licenseType = license;
        } else if (!licenseUrl) {
          publishData.licenseType = COPYRIGHT;
          publishData.otherLicenseDescription = license;
        } else {
          publishData.licenseType = OTHER;
          publishData.otherLicenseDescription = license;
        }

        if (licenseUrl) {
          publishData.licenseUrl = licenseUrl;
        }
      }
    }

    // -- Visibility
    if (fieldSet.has('visibility')) {
      if (tags.includes(VISIBILITY_TAGS.UNLISTED)) {
        publishData.visibility = 'unlisted';
      } else if (tags.includes(VISIBILITY_TAGS.PRIVATE)) {
        publishData.visibility = 'private';
      } else {
        publishData.visibility = 'public';
      }

      // Don't copy scheduled visibility; scheduling is per-upload.
      // Reset first to avoid stale restrictions from previous form values.
      publishData.memberRestrictionOn = false;
      publishData.memberRestrictionTierIds = [];
    }

    // -- Price / Paywall
    if (fieldSet.has('price')) {
      publishData.paywall = PAYWALL.FREE;
      publishData.fiatPurchaseEnabled = false;
      publishData.fiatRentalEnabled = false;
      const rental = parseRentalTag(tags);
      const purchasePrice = parsePurchaseTag(tags);

      if (rental || purchasePrice) {
        publishData.paywall = PAYWALL.FIAT;
      } else if (normalizedFee.amount > 0) {
        publishData.paywall = PAYWALL.SDK;
        publishData.fee = normalizedFee;
      } else {
        publishData.paywall = PAYWALL.FREE;
      }

      if (rental) {
        publishData.fiatRentalEnabled = true;
        publishData.fiatRentalFee = {
          amount: rental.price,
          currency: 'USD',
        };
        publishData.fiatRentalExpiration = {
          value: rental.expirationTimeInSeconds / TO_SECONDS['days'],
          unit: 'days',
        };
      }

      if (purchasePrice) {
        publishData.fiatPurchaseEnabled = true;
        publishData.fiatPurchaseFee = {
          amount: purchasePrice,
          currency: 'USD',
        };
      }
    }

    // -- Membership restrictions
    if (fieldSet.has('visibility') && tags.includes(MEMBERS_ONLY_CONTENT_TAG)) {
      const sourceChannelId = claim.signing_channel?.claim_id || null;
      const targetChannelId = state.publish.channelId;

      // Membership IDs are channel-specific. Copy only when source/destination channels match.
      if (sourceChannelId && sourceChannelId === targetChannelId) {
        let protectedMembershipIds = selectProtectedContentMembershipsForContentClaimId(state, claim.claim_id);

        if (protectedMembershipIds === undefined) {
          await dispatch(doMembershipContentforStreamClaimId(claim.claim_id));
          state = getState();
          protectedMembershipIds = selectProtectedContentMembershipsForContentClaimId(state, claim.claim_id);
        }

        if (protectedMembershipIds && protectedMembershipIds.length > 0) {
          publishData.memberRestrictionOn = true;
          publishData.memberRestrictionTierIds = protectedMembershipIds;
        }
      }
    }

    dispatch(doUpdatePublishForm(publishData));
  };
};
export const doPublish =
  (
    success: (...args: Array<any>) => any,
    fail: (...args: Array<any>) => any,
    previewFn?: (...args: Array<any>) => any,
    payload?: FileUploadSdkParams
  ) =>
  (dispatch: Dispatch, getState: GetState) => {
    if (!previewFn) {
      dispatch({
        type: ACTIONS.PUBLISH_START,
      });
    }

    const state = getState();
    const myClaimForUri = state.publish.claimToEdit;
    const myChannels = selectMyChannelClaims(state) as Array<ChannelClaim> | null | undefined;
    // const myClaims = selectMyClaimsWithoutChannels(state);
    // get redux publish form
    const publishData = selectPublishFormValues(state);
    const { memberRestrictionTierIds, name } = publishData;
    const memberRestrictionStatus = selectMemberRestrictionStatus(state);
    const publishPayload =
      payload ||
      resolvePublishPayload(publishData, myClaimForUri, myChannels, memberRestrictionStatus, Boolean(previewFn));
    const { channel_id: channelClaimId } = publishPayload;
    const existingClaimId = myClaimForUri?.claim_id || '';

    // hit backend to save restricted memberships
    // hit the backend immediately to save the data, we will overwrite it if publish succeeds
    if (channelClaimId && !previewFn) {
      dispatch(
        doSaveMembershipRestrictionsForContent(
          channelClaimId,
          existingClaimId,
          name,
          memberRestrictionStatus.isRestricting ? memberRestrictionTierIds : [],
          existingClaimId ? undefined : true
        )
      );
    }

    if (previewFn) {
      const ESTIMATE_PUBLISH_COST = false;

      if (ESTIMATE_PUBLISH_COST) {
        const payloadSnapshot = { ...publishPayload }; // Lbry alters the payload, so make copy for previewFn

        return Lbry.publish(publishPayload).then((previewResponse: PublishResponse) => {
          return previewFn(payloadSnapshot, previewResponse);
        }, fail);
      } else {
        return previewFn(publishPayload, null);
      }
    }

    return Lbry.publish(publishPayload).then((response: PublishResponse) => {
      // TODO: Restore LbryFirst
      // if (!useLBRYUploader) {
      return success(response); // }
      // publishPayload.permanent_url = response.outputs[0].permanent_url;
      //
      // return LbryFirst.upload(publishPayload)
      //   .then(() => {
      //     // Return original publish response so app treats it like a normal publish
      //     return success(response);
      //   })
      //   .catch((error) => {
      //     return success(response, error);
      //   });
    }, fail);
  };
export const doPublishWithEarlyUpload =
  (tusUrlPromise: Promise<{ tusUrl: string }>, guid: string) => async (dispatch: Dispatch, getState: GetState) => {
    const state = getState();
    const myClaimForUri = state.publish.claimToEdit;
    const myChannels = selectMyChannelClaims(state) as Array<ChannelClaim> | null | undefined;
    const publishData = selectPublishFormValues(state);
    const memberRestrictionStatus = selectMemberRestrictionStatus(state);

    dispatch({ type: ACTIONS.PUBLISH_START });
    navigateTo(`/$/${PAGES.UPLOADS}`);

    try {
      const { tusUrl } = await tusUrlPromise;
      dispatch({
        type: ACTIONS.PUBLISH_PIPELINE_UPDATE,
        data: { id: guid, updates: { stage: 'processing', progress: 0 } },
      });

      const { memberRestrictionTierIds, name } = publishData;
      const publishPayload = resolvePublishPayload(
        publishData,
        myClaimForUri,
        myChannels,
        memberRestrictionStatus,
        false
      );
      const { channel_id: channelClaimId } = publishPayload;
      const existingClaimId = myClaimForUri?.claim_id || '';

      if (channelClaimId) {
        dispatch(
          doSaveMembershipRestrictionsForContent(
            channelClaimId,
            existingClaimId,
            name,
            memberRestrictionStatus.isRestricting ? memberRestrictionTierIds : [],
            existingClaimId ? undefined : true
          )
        );
      }

      const { createClaim } = await import('web/setup/publish-v4-tasks');
      const { pollPublishStatus } = await import('web/setup/publish-v4');

      const token =
        Lbry.getApiRequestHeaders() && Object.keys(Lbry.getApiRequestHeaders()).includes(X_LBRY_AUTH_TOKEN)
          ? Lbry.getApiRequestHeaders()[X_LBRY_AUTH_TOKEN]
          : '';

      const { uploadUrl, guid: _guid, remote_url, publishId: _pid, ...sdkParams } = publishPayload;

      const publishId = await createClaim(token, tusUrl, sdkParams, {
        onSuccess: () => {},
        onFailure: () => {},
      });

      const signingChannel = myChannels?.find((ch: any) => ch.claim_id === channelClaimId);
      const channelBaseUrl =
        signingChannel?.short_url || signingChannel?.canonical_url || signingChannel?.permanent_url;
      const publishedUri = channelBaseUrl
        ? `${channelBaseUrl}/${publishData.name}`
        : buildURI({ streamName: publishData.name, channelName: publishData.channel } as LbryUrlObj, true);
      const isAudio = !!publishData.fileMime && publishData.fileMime.startsWith('audio/');
      const sourceMediaType = publishData.fileMime || (publishData.fileVid ? 'video/mp4' : undefined);
      const streamMetadata = publishData.fileVid
        ? publishData.fileDur
          ? { video: { duration: publishData.fileDur } }
          : {}
        : isAudio && publishData.fileDur
          ? { audio: { duration: publishData.fileDur } }
          : {};
      const pendingClaimId = `pending-${guid}`;
      const fakePendingClaim: any = {
        claim_id: pendingClaimId,
        name: publishData.name,
        permanent_url: publishedUri,
        canonical_url: publishedUri,
        short_url: publishedUri,
        type: 'claim',
        value_type: 'stream',
        confirmations: 0,
        is_channel_signature_valid: !!signingChannel,
        value: {
          title: publishData.title,
          description: publishData.description,
          thumbnail: { url: publishData.thumbnail },
          tags: publishData.tags?.map((t: any) => t.name) || [],
          source: sourceMediaType ? { media_type: sourceMediaType } : undefined,
          ...streamMetadata,
        },
        signing_channel: signingChannel
          ? {
              claim_id: signingChannel.claim_id,
              name: signingChannel.name,
              permanent_url: signingChannel.permanent_url,
              canonical_url: signingChannel.canonical_url,
              value: signingChannel.value,
            }
          : undefined,
        txid: pendingClaimId,
        nout: 0,
        meta: { effective_amount: '0' },
        timestamp: Math.floor(Date.now() / 1000),
      };

      dispatch({
        type: ACTIONS.UPDATE_PENDING_CLAIMS,
        data: {
          claims: [fakePendingClaim],
          options: { overrideTags: true, overrideSigningChannel: true },
        },
      } as UpdatePendingClaimsAction);
      dispatch({ type: ACTIONS.PUBLISH_SET_ACTIVE_FORM, data: { id: null } });
      dispatch({ type: ACTIONS.PUBLISH_SUCCESS, data: {} });

      pollPublishStatus(token, publishId, guid, dispatch)
        .then((sdkResult) => {
          const pendingClaim = sdkResult.outputs[0];
          dispatch({ type: ACTIONS.REMOVE_PENDING_CLAIM_BY_ID, data: { claimId: pendingClaimId } });
          dispatch({
            type: ACTIONS.UPDATE_PENDING_CLAIMS,
            data: {
              claims: [pendingClaim],
              options: { overrideTags: true, overrideSigningChannel: true },
            },
          } as UpdatePendingClaimsAction);
          dispatch({
            type: ACTIONS.PUBLISH_PIPELINE_UPDATE,
            data: {
              id: guid,
              updates: {
                stage: 'published',
                progress: 100,
                uri: pendingClaim.permanent_url || publishedUri,
              },
            },
          });
          dispatch(doCheckPendingClaims(undefined));
        })
        .catch((err: any) => {
          dispatch({ type: ACTIONS.REMOVE_PENDING_CLAIM_BY_ID, data: { claimId: pendingClaimId } });
          dispatch({
            type: ACTIONS.PUBLISH_PIPELINE_UPDATE,
            data: {
              id: guid,
              updates: {
                stage: 'error',
                error:
                  err?.message ||
                  'Publish confirmation failed. Your upload may have been blocked by a browser extension.',
              },
            },
          });
          dispatch(
            doToast({
              isError: true,
              message: __('Publish failed.'),
              subMessage:
                err?.message || __('Confirmation timed out. A browser extension may be blocking the request.'),
              duration: 'long',
            })
          );
        });
    } catch (error: any) {
      dispatch({ type: ACTIONS.PUBLISH_FAIL });
      dispatch({ type: ACTIONS.REMOVE_PENDING_CLAIM_BY_ID, data: { claimId: `pending-${guid}` } });
      dispatch({
        type: ACTIONS.PUBLISH_PIPELINE_UPDATE,
        data: { id: guid, updates: { stage: 'error', error: error?.message } },
      });
      dispatch(doError({ message: typeof error === 'string' ? error : error.message, cause: error.cause }));
    }
  };

// Calls file_list until any reflecting files are done
export const doCheckReflectingFiles = () => (dispatch: Dispatch, getState: GetState) => {
  const state = getState();
  const { checkingReflector } = state.claims;
  let reflectorCheckInterval;

  const checkFileList = async () => {
    const state = getState();
    const reflectingById = selectReflectingById(state);
    const ids = Object.keys(reflectingById);
    const newReflectingById = {};
    const promises = [];

    // TODO: just use file_list({claim_id: Array<claimId>})
    if (Object.keys(reflectingById).length) {
      ids.forEach((claimId) => {
        promises.push(
          Lbry.file_list({
            claim_id: claimId,
          })
        );
      });
      Promise.all(promises)
        .then((results) => {
          results.forEach((res) => {
            if (res.items[0]) {
              const fileListItem = res.items[0];
              const fileClaimId = fileListItem.claim_id;
              const {
                is_fully_reflected: done,
                uploading_to_reflector: uploading,
                reflector_progress: progress,
              } = fileListItem;

              if (uploading) {
                newReflectingById[fileClaimId] = {
                  fileListItem: fileListItem,
                  progress,
                  stalled: !done && !uploading,
                };
              }
            }
          });
        })
        .then(() => {
          dispatch({
            type: ACTIONS.UPDATE_FILES_REFLECTING,
            data: newReflectingById,
          });

          if (!Object.keys(newReflectingById).length) {
            dispatch({
              type: ACTIONS.TOGGLE_CHECKING_REFLECTING,
              data: false,
            });
            clearInterval(reflectorCheckInterval);
          }
        });
    } else {
      dispatch({
        type: ACTIONS.TOGGLE_CHECKING_REFLECTING,
        data: false,
      });
      clearInterval(reflectorCheckInterval);
    }
  };

  // do it once...
  checkFileList();

  // then start the interval if it's not already started
  if (!checkingReflector) {
    dispatch({
      type: ACTIONS.TOGGLE_CHECKING_REFLECTING,
      data: true,
    });
    reflectorCheckInterval = setInterval(() => {
      checkFileList();
    }, 5000);
  }
};
